erklaerung_vorlauf_zum_zeitraumende <- function(vorlauffall=NULL, erklaerungseingang_am=NULL, beendigung_am=NULL, einordnungsnachweis=NULL) {
 .auswahl(vorlauffall,'vorlauffall',c('mietwiderspruch_574b','pachterbenwiderspruch_594d','pachtfortsetzung_595','pachtgerichtsantrag_595','darlehen_zinsbindungsende_493','darlehen_vertragsende_493'))
 .datum(erklaerungseingang_am,'erklaerungseingang_am');ende <- .datum(beendigung_am,'beendigung_am');.text(einordnungsnachweis,'einordnungsnachweis')
 monate <- c(mietwiderspruch_574b=2,pachterbenwiderspruch_594d=3,pachtfortsetzung_595=12,pachtgerichtsantrag_595=9,darlehen_zinsbindungsende_493=3,darlehen_vertragsende_493=3)[[vorlauffall]]
 ablauf <- .frist(erklaerungseingang_am,monate,'monate','ereignis')
 wert <- list(vorlauf_ablauf_am=.iso(ablauf),vorlauf_zum_zeitraumende_eingehalten=ablauf<=ende)
 eingaben <- list(vorlauffall=vorlauffall, erklaerungseingang_am=erklaerungseingang_am, beendigung_am=beendigung_am, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"datum_und_wahrheitswert","BGB_ERKLAERUNG_VORLAUF_ZUM_ZEITRAUMENDE",eingaben,list(list(operation="Gesetzlichen Vorlauf ab tats\u00e4chlichem Erkl\u00e4rungseingang berechnen und mit Beendigung zu Tagesablauf vergleichen.")),eingaben)
 ergebnis$hinweise <- list("\u00a7574bII Zwei-Monats-Vorlauf, \u00a7594dII Drei-Monats-Vorlauf, \u00a7595V Ein-Jahres-Vorlauf oder \u00a7595VII Neun-Monats-Vorlauf. Ereignisbeginn nach\u00a7187I und Ablauf nach\u00a7188; der volle Vorlauf muss sp\u00e4testens mit Ablauf des angegebenen letzten Vertragstages enden. Anders als Beginn eines Tages schlie\u00dft dieser Bezugszeitpunkt den Beendigungstag ein. Keine automatische Anwendung von\u00a7193 und keine automatische Unwirksamkeit versp\u00e4teter Erkl\u00e4rungen. \u00a7574bII2 fehlender rechtzeitiger Vermieterhinweis, \u00a7595V/VII Sonderf\u00e4lle bei h\u00f6chstens zw\u00f6lfmonatiger K\u00fcndigungsfrist und gerichtliche Nachzulassung gesondert; f\u00fcr diese Sonderf\u00e4lle existieren eigene Grundfristen. \u00a7594dII Bewirtschaftung und vollst\u00e4ndige Mitteilung sind rechtliche Voraussetzungen.")
 ergebnis$hinweise <- c(ergebnis$hinweise,list("\u00a7493I/II: Unterrichtung spaetestens drei Kalendermonate vor dem rechtlich feststehenden Ende der Sollzinsbindung beziehungsweise des Darlehensvertrags zu Tagesablauf. Tatsaechlichen Zugang vorwaerts gegen Endtag pruefen; erforderliche Informationsinhalte und Verhaeltnis von Zinsbindung zu Rueckzahlungszeit bleiben rechtliche Qualifikation. Keine automatische Informationspflicht oder Wirksamkeitsentscheidung."))
 ergebnis
}
